#nullable enable

using Marten;
using Wolverine;
// ListenForMessagesFromExternalDatabaseTable lives on Wolverine.RDBMS.Transport.ExternalDbTransportExtensions,
// and the doc page that documents the feature never names a namespace — the mirror's recurring weakness. Found
// by grepping the NuGet package's own XML doc file, which turned out to be a faster tiebreaker than the
// `dotnet run probe.cs` reflection app CLAUDE.md recommends: the .xml ships beside every .dll in
// ~/.nuget/packages and carries fully-qualified names for every documented member. It only lists DOCUMENTED
// members, so absence there proves nothing — but a hit is definitive.
using Wolverine.RDBMS.Transport;
using StockFeed.Contracts;   // StockNoticed — the model-declared foreign event

namespace StockFeed.Landing;

/// <summary>
/// The second thing the model does not tell you about a translation slice — and the one that is genuinely
/// new, because the first (what wakes the trigger) is the automation pattern's question and is already
/// answered in reference-implementations/automation/.
///
/// <c>Event(s) (source system) -> View -> Trigger -> Command -> Event(s)</c> draws a yellow box in our
/// swimlane and says nothing whatever about how it got there. It could be a webhook the warehouse calls, a
/// table the warehouse writes, a queue we listen to, or a poll of their API on a clock — and those four
/// differ in durability, in who is responsible when a notice goes missing, and in whether anything exists to
/// re-read at all.
///
/// **In a real project you would pick ONE and delete the rest.** All three live here because this is a
/// reference: they are selected by <c>Feed:Landing</c> so the same assertions can be run against each, which
/// is what makes this a comparison rather than three programs.
///
/// <code>
///   they call us, and a lost call is THEIR retry to make    -> Webhook
///   they write a row in our database, we poll it durably    -> ExternalTable
///   they offer only a query API, or push nothing at all     -> Poll
/// </code>
///
/// THE DECISION RULE, and it is not "which is easiest to build": **who is responsible for a notice that goes
/// missing, and is there anything left to re-read?** A webhook makes the warehouse responsible and leaves us
/// nothing to recover from. A table and a poll both leave the notice sitting somewhere we can read again.
/// For a feed that never re-sends — the black box of ch.16 — that difference is the whole decision, because
/// a dropped notice is not a delayed number, it is a permanently wrong one.
///
/// WHAT THIS CLASS CANNOT DO, and the reason it is reached through the wakeup hooks: <c>Program.cs</c> is
/// <c>emit</c>, and its only scaffold seams are <c>TranslateStockNoticeWakeup</c>'s. There is no landing
/// hook, so ingest has to be smuggled in through hooks named after a different decision. The two decisions
/// are kept in two files anyway — the coupling is the generator's, not the design's.
/// </summary>
public static class StockFeedLanding
{
    public const string Setting = "Feed:Landing";

    public enum Mechanism { None, Webhook, ExternalTable, Poll }

    /// <summary>
    /// <c>None</c> in tests, and for the same reason the wakeup is: a poll firing mid-test appends notices
    /// into streams other tests are asserting on. Each landing test boots its own host with one of these on.
    /// </summary>
    public static Mechanism Chosen { get; private set; } = Mechanism.None;

    /// <summary>The schema and table the warehouse writes into, for <see cref="Mechanism.ExternalTable"/>.</summary>
    public const string InboundSchema = "stockfeed_inbound";
    public const string InboundTable = "warehouse_notices";

    public static void Choose(IConfiguration config) =>
        Chosen = (config[Setting] ?? "").Trim().ToLowerInvariant() switch
        {
            "webhook" => Mechanism.Webhook,
            "externaltable" or "external-table" or "table" => Mechanism.ExternalTable,
            "poll" => Mechanism.Poll,
            _ => Mechanism.None,
        };

    /// <summary>
    /// MECHANISM B, the registration: Wolverine polls a table the warehouse owns, in our own database, and
    /// moves each row into its transactional inbox before a handler ever sees it.
    ///
    /// This is the only one of the three that needs no cooperation from the warehouse beyond an INSERT, and
    /// the only one that is durable without us writing any durability code: the rows sit there until
    /// Wolverine has them, the inbox holds them until the handler succeeds, failures go to the ordinary dead
    /// letter storage, and an advisory lock means several nodes cannot double-read. For a legacy black box
    /// with no messaging of its own, it is the answer the Wolverine docs are written for.
    ///
    /// MessageType is set because a non-Wolverine writer sends no message type name; without it Wolverine
    /// cannot know what to deserialise the JSON into and the endpoint is limited to nothing. Sequential
    /// because notices for one product must not be raced against each other by parallel handlers — the
    /// decider would refuse the loser as stale, which is correct but wasteful.
    /// </summary>
    public static void ConfigureWolverine(WolverineOptions opts)
    {
        if (Chosen != Mechanism.ExternalTable) return;

        opts.ListenForMessagesFromExternalDatabaseTable(InboundSchema, InboundTable, table =>
            {
                table.IdColumnName = "id";
                table.JsonBodyColumnName = "body";
                table.TimestampColumnName = "added";
                table.MessageType = typeof(StockNoticed);

                // A second a tick rather than the default ten. This is the knob that decides how late our
                // stock is, and it is a free choice ONLY because ingest is idempotent — the same row can
                // never be applied twice, so polling faster costs reads and nothing else.
                table.PollingInterval = TimeSpan.FromSeconds(1);

                // Let Wolverine create the table at startup. In production the warehouse's DBA owns it and
                // this would be false, with the schema agreed out of band — which is worth saying out loud,
                // because an auto-created table is exactly the kind of convenience that hides a contract.
                table.AllowWolverineControl = true;
            })
            .Sequential();
    }

    /// <summary>
    /// MECHANISM C, the clock: we call them. The only option when the far side pushes nothing, and the only
    /// one that needs a HIGH-WATER MARK of its own — a push feed's position is implicit in what arrived,
    /// while a pull feed has to remember where it got to or it re-reads the world every tick.
    ///
    /// That checkpoint is the mechanism's real cost. It is a row we own, it can be wrong, and which side of
    /// the ingest it is advanced on decides the failure mode: advance before, and a crash loses notices for
    /// good; advance after, and a crash re-reads them. This one advances AFTER, because the domain dedupe
    /// makes a re-read free and a lost notice from a feed that never re-sends is unrecoverable.
    /// </summary>
    public static void RegisterServices(WebApplicationBuilder builder)
    {
        if (Chosen != Mechanism.Poll) return;
        builder.Services.AddSingleton<IHostedService>(sp => new WarehousePollClock(sp));
    }
}
